#include <iostream>
bool isPositive(int n) {
    std::cout << "Checking if positive: " << n << std::endl;
    return n > 0;
}
int main() {
    int a = -1;
    int b = 5;
    // The second call to isPositive is skipped because a is negative
    if (isPositive(a) || isPositive(b)) {
        std::cout << "At least one number is positive." << std::endl;
    }
    return 0;
}
